/**
 * Canonical messages signed with a registered trading key, for the v1 clearing API.
 *
 * Byte-for-byte equal to `crates/zfx-perps-clearing/src/wire.rs`; `test/clearing_vectors.json`
 * (generated by Rust) pins both. Each message is a `|`-separated UTF-8 string starting with a
 * versioned domain tag, then the chain id and the clearing contract. The trading key signs the
 * UTF-8 bytes, unhashed. Booleans are `0`/`1`, enums upper-case words, integers base-10 without
 * leading zeros, hashes lower-case hex.
 */
import { sha256 } from "@noble/hashes/sha2";
import { bytesToHex } from "@noble/hashes/utils";
import type { OrderFields, OrderType, Side, TimeInForce } from "./types.js";

export const ORDER_V1 = "zfx-perps-order-v1";
export const CANCEL_V1 = "zfx-perps-cancel-v1";
export const MIN_NONCE_V1 = "zfx-perps-min-nonce-v1";
export const WITHDRAW_V1 = "zfx-perps-withdraw-v1";
export const MARGIN_V1 = "zfx-perps-margin-v1";
export const AUTH_V1 = "zfx-perps-auth-v1";

export const U16_MAX = 0xffff;
export const U32_MAX = 0xffff_ffffn;
export const U64_MAX = (1n << 64n) - 1n;
export const U128_MAX = (1n << 128n) - 1n;
export const I128_MIN = -(1n << 127n);
export const I128_MAX = (1n << 127n) - 1n;

/** Thrown when a field would make a message the contract rejects or could misparse. */
export class WireError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "WireError";
  }
}

/** NEAR account ids: 2-64 chars of `[a-z0-9._-]` (same rule as `wire::valid_account`). */
export const validAccountId = (s: string) => /^[a-z0-9._-]{2,64}$/.test(s);
/** Market ids: 3-32 chars of `[A-Z0-9-]`, e.g. `OPUS-PERP`. */
export const validMarketId = (s: string) => /^[A-Z0-9-]{3,32}$/.test(s);
/** Chain ids: 1-32 chars of `[a-z0-9:-]`, e.g. `near:testnet`. */
export const validChainId = (s: string) => /^[a-z0-9:-]{1,32}$/.test(s);
/** 32-byte hash as 64 lower-case hex chars. */
export const validHash = (s: string) => /^[0-9a-f]{64}$/.test(s);

function check(ok: boolean, what: string, v: string): string {
  if (!ok) throw new WireError(`invalid ${what}: ${JSON.stringify(v)}`);
  return v;
}
const chain = (s: string) => check(validChainId(s), "chain id", s);
const account = (s: string, what = "account id") => check(validAccountId(s), what, s);
const market = (s: string) => check(validMarketId(s), "market id", s);
const hash = (s: string, what: string) => check(validHash(s), `${what} (64 lower-case hex chars)`, s);

/** Unsigned integer in `[0, max]` as base-10. Rejects JS numbers that are not safe integers. */
export function uint(v: bigint | number | string, max: bigint, what: string): string {
  const b = toBigInt(v, what);
  if (b < 0n || b > max) throw new WireError(`${what} out of range: ${b}`);
  return b.toString();
}

function int(v: bigint | number | string, min: bigint, max: bigint, what: string): string {
  const b = toBigInt(v, what);
  if (b < min || b > max) throw new WireError(`${what} out of range: ${b}`);
  return b.toString();
}

/** Strict integer conversion: decimal strings, bigints, or safe-integer numbers only. */
export function toBigInt(v: bigint | number | string, what = "value"): bigint {
  if (typeof v === "bigint") return v;
  if (typeof v === "number") {
    if (!Number.isSafeInteger(v)) throw new WireError(`${what} is not a safe integer: ${v}`);
    return BigInt(v);
  }
  if (typeof v === "string" && /^-?[0-9]+$/.test(v)) return BigInt(v);
  throw new WireError(`${what} is not an integer: ${JSON.stringify(v)}`);
}

const SIDES: readonly Side[] = ["BUY", "SELL"];
const TYPES: readonly OrderType[] = ["LIMIT", "MARKET"];
const TIFS: readonly TimeInForce[] = ["GTC", "IOC", "FOK"];
function oneOf<T extends string>(v: T, all: readonly T[], what: string): T {
  if (!all.includes(v)) throw new WireError(`invalid ${what}: ${JSON.stringify(v)}`);
  return v;
}

const bit = (b: boolean) => (b ? "1" : "0");

/** The exact string the trading key signs for an order (`SignedOrder::message`). */
export function orderMessage(o: OrderFields): string {
  return [
    ORDER_V1,
    chain(o.chainId),
    account(o.clearingContract, "clearing contract"),
    account(o.accountId),
    market(o.marketId),
    oneOf(o.side, SIDES, "side"),
    oneOf(o.type, TYPES, "order type"),
    uint(o.price, U64_MAX, "price"),
    uint(o.quantity, U64_MAX, "quantity"),
    bit(o.reduceOnly),
    bit(o.postOnly),
    oneOf(o.timeInForce, TIFS, "time in force"),
    uint(o.nonce, U64_MAX, "nonce"),
    uint(o.expiryNs, U64_MAX, "expiryNs"),
    uint(o.clientOrderId, U64_MAX, "clientOrderId"),
    uint(o.maxFeeBps, BigInt(U16_MAX), "maxFeeBps"),
    hash(o.policyHash, "policy hash"),
  ].join("|");
}

/**
 * Mirrors `SignedOrder::well_formed` plus the message validation: positive price and quantity,
 * post-only only on LIMIT GTC, MARKET never GTC. Throws `WireError` otherwise.
 */
export function assertWellFormed(o: OrderFields): void {
  orderMessage(o);
  if (toBigInt(o.quantity) <= 0n) throw new WireError("quantity must be > 0");
  if (toBigInt(o.price) <= 0n) throw new WireError("price must be > 0");
  if (o.postOnly && (o.type === "MARKET" || o.timeInForce !== "GTC")) throw new WireError("postOnly requires a LIMIT GTC order");
  if (o.type === "MARKET" && o.timeInForce === "GTC") throw new WireError("MARKET orders must be IOC or FOK");
}

export function utf8(s: string): Uint8Array {
  return new TextEncoder().encode(s);
}

export function sha256Hex(data: Uint8Array | string): string {
  return bytesToHex(sha256(typeof data === "string" ? utf8(data) : data));
}

/** On-chain order id: lower-case hex sha256 of the order message. */
export function orderHash(o: OrderFields): string {
  return sha256Hex(orderMessage(o));
}

/** Cancel one order by hash. Carries the order's expiry so the record can be pruned later. */
export function cancelMessage(chainId: string, contract: string, accountId: string, orderHashHex: string, expiryNs: bigint | number | string): string {
  return [CANCEL_V1, chain(chainId), account(contract, "clearing contract"), account(accountId), hash(orderHashHex, "order hash"), uint(expiryNs, U64_MAX, "expiryNs")].join("|");
}

/** Raise the nonce floor: every order with a smaller nonce becomes unfillable. */
export function minNonceMessage(chainId: string, contract: string, accountId: string, minNonce: bigint | number | string): string {
  return [MIN_NONCE_V1, chain(chainId), account(contract, "clearing contract"), account(accountId), uint(minNonce, U64_MAX, "minNonce")].join("|");
}

/** Withdraw free collateral `token` to the account itself. `nonce` must exceed the account's action nonce. */
export function withdrawMessage(chainId: string, contract: string, accountId: string, token: string, amount: bigint | number | string, nonce: bigint | number | string): string {
  return [WITHDRAW_V1, chain(chainId), account(contract, "clearing contract"), account(accountId), account(token, "token"), uint(amount, U128_MAX, "amount"), uint(nonce, U64_MAX, "nonce")].join("|");
}

/** Move collateral into (`delta > 0`) or out of (`delta < 0`) one isolated position. */
export function marginMessage(chainId: string, contract: string, accountId: string, marketId: string, delta: bigint | number | string, nonce: bigint | number | string): string {
  return [MARGIN_V1, chain(chainId), account(contract, "clearing contract"), account(accountId), market(marketId), int(delta, I128_MIN, I128_MAX, "delta"), uint(nonce, U64_MAX, "nonce")].join("|");
}

/** Authenticates private REST reads and WebSocket channels (gateway only, never on-chain). */
export function authMessage(chainId: string, contract: string, accountId: string, tsMs: bigint | number | string): string {
  return [AUTH_V1, chain(chainId), account(contract, "clearing contract"), account(accountId), uint(tsMs, U64_MAX, "ts")].join("|");
}
